   105  ExifData *
   106  exif_data_new_mem (ExifMem *mem)
   107  {
   108          ExifData *data;
   109          unsigned int i;
   110
   111          if (!mem)
   112                  return NULL;
   113
   114          data = exif_mem_alloc (mem, sizeof (ExifData));
   115          if (!data)
   116                  return (NULL);
   117          data->priv = exif_mem_alloc (mem, sizeof (ExifDataPrivate));
   118          if (!data->priv) {
   119                  exif_mem_free (mem, data);
   120                  return (NULL);
   121          }
   122          data->priv->ref_count = 1;
   123
   124          data->priv->mem = mem;
   125          exif_mem_ref (mem);
   126
   127          for (i = 0; i < EXIF_IFD_COUNT; i++) {
   128                  data->ifd[i] = exif_content_new_mem (data->priv->mem);
   129                  if (!data->ifd[i]) {
   130                          exif_data_free (data);
   131                          return (NULL);
   132                  }
   133                  data->ifd[i]->parent = data;
   134          }
