   162  static int
   163  exif_data_load_data_entry (ExifData *data, ExifEntry *entry,
   164                             const unsigned char *d,
   165                             unsigned int size, unsigned int offset)
   166  {
   167          unsigned int s, doff;
   168
   169          entry->tag        = exif_get_short (d + offset + 0, data->priv->order);
   170          entry->format     = exif_get_short (d + offset + 2, data->priv->order);
   171          entry->components = exif_get_long  (d + offset + 4, data->priv->order);
   172
   173          /* FIXME: should use exif_tag_get_name_in_ifd here but entry->parent
   174           * has not been set yet
   175           */
   176          exif_log (data->priv->log, EXIF_LOG_CODE_DEBUG, "ExifData",
   177                    "Loading entry 0x%x ('%s')...", entry->tag,
   178                    exif_tag_get_name (entry->tag));
   179
   180          /* {0,1,2,4,8} x { 0x00000000 .. 0xffffffff }
   181           *   -> { 0x000000000 .. 0x7fffffff8 } */
   182          s = exif_format_get_size(entry->format) * entry->components;
   183          if ((s < entry->components) || (s == 0)){
   184                  return 0;
   185          }
   186
   187          /*
   188           * Size? If bigger than 4 bytes, the actual data is not
   189           * in the entry but somewhere else (offset).
   190           */
   191          if (s > 4)
   192                  doff = exif_get_long (d + offset + 8, data->priv->order);
   193          else
   194                  doff = offset + 8;
   195
   196          /* Sanity checks */
   197          if (doff >= size) {
   198                  exif_log (data->priv->log, EXIF_LOG_CODE_DEBUG, "ExifData",
   199                                    "Tag starts past end of buffer (%u > %u)", doff, size);
   200                  return 0;
   201          }
   202
   203          if (s > size - doff) {
   204                  exif_log (data->priv->log, EXIF_LOG_CODE_DEBUG, "ExifData",
   205                                    "Tag data goes past end of buffer (%u > %u)", doff+s, size);
   206                  return 0;
   207          }
   208
   209          entry->data = exif_data_alloc (data, s);
   210          if (entry->data) {
   211                  entry->size = s;
   212                  memcpy (entry->data, d + doff, s);
   213          } else {
   214                  EXIF_LOG_NO_MEMORY(data->priv->log, "ExifData", s);
   215                  return 0;
   216          }
   217
   218          /* If this is the MakerNote, remember the offset */
   219          if (entry->tag == EXIF_TAG_MAKER_NOTE) {
   220                  if (!entry->data) {
   221                          exif_log (data->priv->log, EXIF_LOG_CODE_DEBUG, "ExifData",
   222                                            "MakerNote found with empty data");
   223                  } else if (entry->size > 6) {
   224                          exif_log (data->priv->log,
   225                                                 EXIF_LOG_CODE_DEBUG, "ExifData",
   226                                                 "MakerNote found (%02x %02x %02x %02x "
   227                                                 "%02x %02x %02x...).",
   228                                                 entry->data[0], entry->data[1], entry->data[2],
   229                                                 entry->data[3], entry->data[4], entry->data[5],
   230                                                 entry->data[6]);
   231                  }
   232                  data->priv->offset_mnote = doff;
   233          }
   234          return 1;
   235  }
