   323  static void
   324  exif_data_load_data_thumbnail (ExifData *data, const unsigned char *d,
   325                                 unsigned int ds, ExifLong o, ExifLong s)
   326  {
   327          /* Sanity checks */
   328          if (o >= ds) {
   329                  exif_log (data->priv->log, EXIF_LOG_CODE_DEBUG, "ExifData", "Bogus thumbnail offset (%u).", o);
   330                  return;
   331          }
   332          if (CHECKOVERFLOW(o,ds,s)) {
   333                  exif_log (data->priv->log, EXIF_LOG_CODE_DEBUG, "ExifData", "Bogus thumbnail size (%u), max would be %u.", s, ds-o);
   334                  return;
   335          }
   336          if (data->data)
   337                  exif_mem_free (data->priv->mem, data->data);
   338          if (!(data->data = exif_data_alloc (data, s))) {
   339                  EXIF_LOG_NO_MEMORY (data->priv->log, "ExifData", s);
   340                  data->size = 0;
   341                  return;
   342          }
   343          data->size = s;
   344          memcpy (data->data, d + o, s);
   345  }
