   365  /*! Calculate the recursion cost added by one level of IFD loading.
   366   *
   367   * The work performed is related to the cost in the exponential relation
   368   *   work=1.1**cost
   369   */
   370  static unsigned int
   371  level_cost(unsigned int n)
   372  {
   373      static const double log_1_1 = 0.09531017980432493;
   374
   375          /* Adding 0.1 protects against the case where n==1 */
   376          return ceil(log(n + 0.1)/log_1_1);
   377  }
