   379  /*! Load data for an IFD.
   380   *
   740                          exif_set_short (*d + 6 + offset + 2, data->priv->order,
   741                                          EXIF_FORMAT_LONG);
   742                          exif_set_long  (*d + 6 + offset + 4, data->priv->order,
   743                                          1);
   744                          exif_set_long  (*d + 6 + offset + 8, data->priv->order,
   745                                          data->size);
   746                          offset += 12;
   747                  }
   748
   749                  break;
   750          default:
   751                  break;
   752          }
   753
   754          /* Sort the directory according to TIFF specification */
   755          qsort (*d + 6 + offset - (ifd->count + n_ptr + n_thumb) * 12,
   756                 (ifd->count + n_ptr + n_thumb), 12,
   757                 (data->priv->order == EXIF_BYTE_ORDER_INTEL) ? cmp_func_intel : cmp_func_motorola);
   758
   759          /* Correctly terminate the directory */
   760          if (i == EXIF_IFD_0 && (data->ifd[EXIF_IFD_1]->count ||
   761                                  data->size)) {
   762
   763                  /*
   764                   * We are saving IFD 0. Tell where IFD 1 starts and save
   765                   * IFD 1.
   766                   */
   767                  exif_set_long (*d + 6 + offset, data->priv->order, *ds - 6);
   768                  exif_data_save_data_content (data, data->ifd[EXIF_IFD_1], d, ds,
   769                                               *ds - 6);
   770          } else
   771                  exif_set_long (*d + 6 + offset, data->priv->order, 0);
   772  }
