   784  /*! If MakerNote is recognized, load it.
   785   *
   786   * \param[in,out] data #ExifData
   787   * \param[in] d pointer to raw EXIF data
   788   * \param[in] ds length of data at d
   789   */
   790  static void
   791  interpret_maker_note(ExifData *data, const unsigned char *d, unsigned int ds)
   792  {
   793          int mnoteid;
   794          ExifEntry* e = exif_data_get_entry (data, EXIF_TAG_MAKER_NOTE);
   795          if (!e)
   796                  return;
   797
   798          if ((mnoteid = exif_mnote_data_olympus_identify (data, e)) != 0) {
   799                  exif_log (data->priv->log, EXIF_LOG_CODE_DEBUG,
   800                          "ExifData", "Olympus MakerNote variant type %d", mnoteid);
   801                  data->priv->md = exif_mnote_data_olympus_new (data->priv->mem);
   802
   803          } else if ((mnoteid = exif_mnote_data_canon_identify (data, e)) != 0) {
   804                  exif_log (data->priv->log, EXIF_LOG_CODE_DEBUG,
   805                          "ExifData", "Canon MakerNote variant type %d", mnoteid);
   806                  data->priv->md = exif_mnote_data_canon_new (data->priv->mem, data->priv->options);
   807
   808          } else if ((mnoteid = exif_mnote_data_fuji_identify (data, e)) != 0) {
   809                  exif_log (data->priv->log, EXIF_LOG_CODE_DEBUG,
   810                          "ExifData", "Fuji MakerNote variant type %d", mnoteid);
   811                  data->priv->md = exif_mnote_data_fuji_new (data->priv->mem);
   812
   813          /* NOTE: Must do Pentax detection last because some of the
   814           * heuristics are pretty general. */
   815          } else if ((mnoteid = exif_mnote_data_pentax_identify (data, e)) != 0) {
   816                  exif_log (data->priv->log, EXIF_LOG_CODE_DEBUG,
   817                          "ExifData", "Pentax MakerNote variant type %d", mnoteid);
   818                  data->priv->md = exif_mnote_data_pentax_new (data->priv->mem);
   819          }
   820
   821          /*
   822           * If we are able to interpret the maker note, do so.
   823           */
   824          if (data->priv->md) {
   825                  exif_mnote_data_log (data->priv->md, data->priv->log);
   826                  exif_mnote_data_set_byte_order (data->priv->md,
   827                                                  data->priv->order);
   828                  exif_mnote_data_set_offset (data->priv->md,
   829                                              data->priv->offset_mnote);
   830                  exif_mnote_data_load (data->priv->md, d, ds);
   831          }
   832  }
